// A human ON opens the window; a human OFF closes it again. The panel sends
// explicit ON/OFF (never TOGGLE), so this is unambiguous.
const now = Date.now();
const holdMs = (flow.get('hold_min') || 10) * 60000;
const cmd = (msg.payload === undefined || msg.payload === null)
    ? ''
    : msg.payload.toString().trim().toUpperCase();

if (cmd === 'ON') {
    // Our own re-assert must not restart the window for ever.
    if (now > (flow.get('ignore_on') || 0)) {
        flow.set('hold_until', now + holdMs);
        flow.set('pending_off', false);
    }
    node.status({ fill: 'green', shape: 'dot', text: 'holding' });
} else if (cmd === 'OFF') {
    flow.set('hold_until', 0);
    flow.set('pending_off', false);
    node.status({ fill: 'grey', shape: 'ring', text: 'idle' });
}

return null;

// OFF from the radar's empty-room automation: swallow it while the window is
// open and remember that it was wanted, so the reconcile timer can honour it
// once the window has expired. Outside the window it is passed straight on.
const now = Date.now();
const cmd = (msg.payload === undefined || msg.payload === null)
    ? ''
    : msg.payload.toString().trim().toUpperCase();

if (cmd === 'OFF') {
    if (now < (flow.get('hold_until') || 0)) {
        flow.set('pending_off', true);
        node.status({ fill: 'yellow', shape: 'dot', text: 'OFF deferred' });
        return null;
    }
    flow.set('pending_off', false);
    return { topic: 'cmnd/light/POWER', payload: 'OFF', qos: 0, retain: false };
}

if (cmd === 'ON') {
    return { topic: 'cmnd/light/POWER', payload: 'ON', qos: 0, retain: false };
}

return null;

// Belt and braces: if the light reports OFF while the window is open, turn it
// back on. Catches OFF commands that never came through the gate (a Tasmota
// timer or rule, a physical switch that reports its state).
const now = Date.now();
const power = (msg.payload && msg.payload.POWER)
    ? msg.payload.POWER.toString().toUpperCase()
    : '';

if (power !== 'OFF') return null;
if (now >= (flow.get('hold_until') || 0)) return null;

flow.set('pending_off', true);
flow.set('ignore_on', now + 5000);
return { topic: 'cmnd/light/POWER', payload: 'ON', qos: 0, retain: false };

// Once the window has expired, honour a deferred OFF exactly once, so a room
// that really is empty still ends up dark. A later human ON clears the flag.
const now = Date.now();
if (!flow.get('pending_off')) return null;
if (now < (flow.get('hold_until') || 0)) return null;

flow.set('pending_off', false);
return { topic: 'cmnd/light/POWER', payload: 'OFF', qos: 0, retain: false };
